[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$ProjectRoot,[Parameter(Mandatory=$true)][string]$PacketPath)
$ErrorActionPreference='Stop';$root=(Resolve-Path $ProjectRoot).Path;if([IO.Path]::IsPathRooted($PacketPath)){throw 'PacketPath must be project-relative.'};$rel=$PacketPath.Replace('\','/').Trim();if($rel.Contains('..')-or $rel -notmatch '^ES/Output/.+\.json$'){throw 'PacketPath must remain under ES/Output.'};$full=Join-Path $root ($rel.Replace('/',[IO.Path]::DirectorySeparatorChar));if(-not(Test-Path $full -PathType Leaf)){throw "Unity evidence packet missing: $rel"};$p=[Text.UTF8Encoding]::new($false,$true).GetString([IO.File]::ReadAllBytes((Resolve-Path $full)))|ConvertFrom-Json;foreach($x in @('schemaVersion','layer','command','result','evidenceLevel','log','generatedProjectClaim','unityClaim','console','reload','tests','staleWhen')){if($null -eq $p.PSObject.Properties[$x]){throw "Unity evidence field missing: $x"}};if([string]$p.schemaVersion -ne '1'-or [string]$p.evidenceLevel -notmatch '^S[0-6]$'){throw 'Invalid Unity evidence schema or level.'};if([string]$p.layer -eq 'dotnet-build'-and [bool]$p.unityClaim){throw 'dotnet-build cannot claim Unity evidence.'};if([string]$p.result -eq 'passed'-and [string]$p.log -eq 'not-run'){throw 'Passed evidence requires a log or result artifact.'};Write-Output "PASS: Unity evidence packet preserves layer separation and unverified boundaries: $rel"
